# Let me check specifically for elements on page 59 (which would be id 59 in 1-indexed)
import json

with open('/app/resources/treasury_bulletin_2003_03.json', 'r') as f:
    data = json.load(f)

doc = data['document']
elements = doc.get('elements', [])

# Find elements that are specifically on page 59 (using page_id in bbox)
for i, elem in enumerate(elements):
    if isinstance(elem, dict):
        bbox = elem.get('bbox', [])
        for coord in bbox:
            if coord.get('page_id') == 59:
                content = str(elem.get('content', ''))
                # Look for yield data
                if 'Aa' in content and ('bond' in content.lower() or 'yield' in content.lower()):
                    print(f"Element {i} on page 59:")
                    print(content[:2500])
                    print("===")

# If nothing found, try page 60 as well
print("\n\nSearching page 60:")
for i, elem in enumerate(elements):
    if isinstance(elem, dict):
        bbox = elem.get('bbox', [])
        for coord in bbox:
            if coord.get('page_id') == 60:
                content = str(elem.get('content', ''))
                if 'Aa' in content and ('bond' in content.lower() or 'yield' in content.lower()):
                    print(f"Element {i} on page 60:")
                    print(content[:2500])
                    print("===")
EOF
